code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    # The solid 2-line marks the side toward which the pieces slide.
    if all(v == 2 for v in grid[0]):
        dr, dc = 1, 0
    elif all(row[-1] == 2 for row in grid):
        dr, dc = 0, -1
    elif all(v == 2 for v in grid[-1]):
        dr, dc = -1, 0
    elif all(row[0] == 2 for row in grid):
        dr, dc = 0, 1
    else:
        raise ValueError("No solid 2-line")

    seen = set()
    pieces = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, 2) or (r, c) in seen:
                continue
            cells = {(r, c)}
            seen.add((r, c))
            stack = [(r, c)]
            while stack:
                y, x = stack.pop()
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); cells.add((yy,xx)); stack.append((yy,xx))
            pieces.append([color, cells])

    # Let pieces nearest the marked edge settle first, so farther pieces stack on them.
    def edge_key(piece):
        cells = piece[1]
        if dr == 1: return -max(r for r,c in cells)
        if dr == -1: return min(r for r,c in cells)
        if dc == 1: return -max(c for r,c in cells)
        return min(c for r,c in cells)
    pieces.sort(key=edge_key)
    occupied = {(r,c) for r in range(h) for c in range(w) if grid[r][c] == 2}
    result = [[0]*w for _ in range(h)]
    for r,c in occupied: result[r][c] = 2
    for color, cells in pieces:
        while True:
            shifted = {(r+dr,c+dc) for r,c in cells}
            if any(r < 0 or r >= h or c < 0 or c >= w or (r,c) in occupied for r,c in shifted):
                break
            cells = shifted
        for r,c in cells:
            result[r][c] = color
            occupied.add((r,c))
    return result
'''
